@PostMapping("/pagamentos")
ResponseEntity<PagamentoResponse> pagar(@RequestHeader("Idempotency-Key") String chave,
                                        @Valid @RequestBody PagamentoRequest req) {
    return idempotencia.buscar(chave)
        .map(ResponseEntity::ok)
        .orElseGet(() -> {
            PagamentoResponse resp = service.pagar(req);
            idempotencia.salvar(chave, resp); // UNIQUE(chave) no banco
            return ResponseEntity.status(HttpStatus.CREATED).body(resp);
        });
}

