// pedido.proto
syntax = "proto3";

service PedidoService {
  rpc Buscar (BuscarPedidoRequest) returns (Pedido);
  rpc AcompanharStatus (BuscarPedidoRequest) returns (stream StatusAtualizado);
}

message BuscarPedidoRequest { int64 id = 1; }
message Pedido { int64 id = 1; string status = 2; double total = 3; }
message StatusAtualizado { string status = 1; }
